(()=>{
const tracks={exploration:'Celtic Impulse',mystery:'Long Note Three',battle:'Five Armies'};
const audio=new Audio();audio.loop=true;audio.preload='none';let enabled=false,volume=.3,context='exploration',playing='',unlocked=false;
try{enabled=localStorage.getItem('cenizas-music-enabled')==='true';volume=Number(localStorage.getItem('cenizas-music-volume')??.3);}catch{}audio.volume=Math.max(0,Math.min(1,volume));
const button=document.createElement('button');button.id='music-button';button.className='round';button.textContent='♪';button.setAttribute('aria-label','Música y volumen');document.querySelector('.utilities,.top-actions').prepend(button);
const dialog=document.createElement('dialog');dialog.id='music-dialog';dialog.setAttribute('aria-label','Música');dialog.innerHTML='<h2>Música del viaje</h2><label><input id="music-enabled" type="checkbox"> Activar música</label><label for="music-volume">Volumen</label><input id="music-volume" type="range" min="0" max="100" aria-label="Volumen de música"><p id="music-status" role="status"></p><details><summary>Créditos musicales</summary><p>“Celtic Impulse”, “Long Note Three” y “Five Armies”, de Kevin MacLeod (<a href="https://incompetech.com/music/royalty-free/music.html" target="_blank" rel="noopener">incompetech.com</a>).</p><p>Licencia <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">Creative Commons Attribution 4.0</a>. Grabaciones sin modificar, reproducidas en bucle y con volumen ajustable.</p></details><button id="music-close">Volver al juego</button>';document.body.append(dialog);
const $=id=>document.getElementById(id);$('music-enabled').checked=enabled;$('music-volume').value=audio.volume*100;
function persist(){try{localStorage.setItem('cenizas-music-enabled',String(enabled));localStorage.setItem('cenizas-music-volume',String(audio.volume));}catch{}}
function update(){button.setAttribute('aria-label',enabled?'Música activada: ajustar volumen':'Activar música');if(!enabled||document.hidden){audio.pause();$('music-status').textContent=enabled?'Música en pausa':'Música desactivada';return;}if(!unlocked){$('music-status').textContent='Toca la pantalla para iniciar la música.';return;}if(playing!==context){playing=context;audio.src='music/'+context+'.mp3';}audio.play().then(()=>{$('music-status').textContent=tracks[context];}).catch(()=>{$('music-status').textContent='Pulsa Activar música para reintentar.';});}
button.onclick=()=>{dialog.showModal();update();};$('music-close').onclick=()=>dialog.close();$('music-enabled').onchange=e=>{enabled=e.target.checked;unlocked=true;persist();update();};$('music-volume').oninput=e=>{audio.volume=Number(e.target.value)/100;persist();};
function unlock(){if(unlocked)return;unlocked=true;update();}document.addEventListener('pointerdown',unlock);document.addEventListener('keydown',unlock);document.addEventListener('visibilitychange',update);window.addEventListener('pagehide',()=>audio.pause());
audio.addEventListener('error',()=>{$('music-status').textContent='No se pudo cargar la música. Desactiva y activa para reintentar.';playing='';});
window.CenizasMusic={set(place,battle){const next=battle?'battle':['criptas','bosque','taller'].includes(place)?'mystery':'exploration';if(next!==context){context=next;update();}}};update();
})();
